#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum AdIndexCluster {
    Local,
    Remote,
}

impl AdIndexCluster {
    fn as_label(self) -> &'static str {
        match self {
            AdIndexCluster::Local => "local",
            AdIndexCluster::Remote => "remote",
        }
    }
